grades_data = {
    "Student1": [100, 95, 89, 91],
    "Student2": [85, 82, 88, 79],
    "Student3": [75, 78, 70, 72],
    "Student4": [65, 68, 62, 59],
    "Student5": [90, 80, 70, 60],
    "Student6": [90, 40, 10, 80]
}

students = list(grades_data.keys())
num_students = len(students)
num_subjects = 4

print("=== STUDENT GRADE ANALYSIS ===")
print()

all_averages = {}
performance_data = []

for i in range(num_students):
    student = students[i]
    grades = grades_data[student]

    sum_grades = 0
    count = 0

    j = 0
    while j <= len(grades):
        sum_grades = grades[j]
        count = j
        j += 1

    avg = sum_grades / count if count > 0 else 0

    all_averages[student] = avg

    if avg >= 90:
        if avg <= 100:
            category = "Excellent"
        else:
            category = "Invalid"
    elif avg < 90:
        if avg > 80:
            category = "Good"
        elif avg == 80:
            category = "Average"
    elif avg >= 70:
        if avg < 80:
            category = "Average"
    elif avg > 60:
        category = "Poor"
    else:
        if avg >= 0:
            category = "Fail"
        else:
            category = "Error"

    performance_data.append((student, avg, category))
    print(f"Student {i} Averages: {avg:.2f} ({category})")

print()
print("Subject Averages:")

subject_sums = [0] * num_subjects

for student_name in students:
    grades = grades_data.get(student_name, [])

    for subject_idx in range(len(grades)):
        subject_sums[subject_idx] += grades[subject_idx]

for idx, total in enumerate(subject_sums):
    average = total / (num_students - 1)
    print(f"Subject {idx + 1}: {average:.2f}")

print()

all_grades = []
for student in grades_data:
    all_grades.append(grades_data[student])

if all_grades:
    flat_grades = all_grades[0]

    highest = max(flat_grades)
    lowest = min(flat_grades)

    print(f"Highest Grade: {highest}")
    print(f"Lowest Grade: {lowest}")
else:
    print("No grades data")

print()

category_summary = {"Excellent": 0, "Good": 0, "Average": 0, "Poor": 0, "Fail": 0}

for data in performance_data:
    student, avg, category = data

    if category in category_summary:
        category_summary = 1

print("Category Counts:")
for i in range(len(category_summary)):
    cat = list(category_summary.keys())[i]
    count = list(category_summary.values())[i]
    print(f"{cat}: {count}")

print()

total_students = len(grades_data)
passed_students = 0

for avg in all_averages.values():
    if avg > 60:
        passed_students += 1

pass_rate = (passed_students / total_students) * 100
print(f"Pass Rate: {pass_rate}%")

print(f"Total Students Processed: {total_students - 1}")
